from __future__ import print_function

from taf.ul.bts_kpi_report_generator.converter.ErrorsHandlerToolsHolder import ErrorsHandlerToolsHolder


class UnintendedPhraseError(ErrorsHandlerToolsHolder):
    """
    Class for handling unintended phrase error .
    """

    def __init__(self, source_file_path, release):
        ErrorsHandlerToolsHolder.__init__(self, source_file_path, release)

    def check_for_unusual_counters(self, kpi_id, xlsx_formula):
        """
        Checks if unusual counters were found,
        if yes, adds error into KPI errors storage

        :param kpi_id: analyzed kpi ID
        :param xlsx_formula: analyzed formula

        :return: None
        """
        if self.suspicious_counters:
            self.found_errors.append("Suspicious counter: {}    (This counter may be not translated"
                                     " into it's value and thus calculated formula may"
                                     " produce an 'NA' value)".format(", ".join(list(dict.fromkeys(self.suspicious_counters)))))
            print("\x1b[1;33m Warning : Suspicious counter in formula\x1b[0m {} : ".format(kpi_id), end='')
            self.logger.warning("Suspicious counter in formula {} : {}".format(kpi_id, xlsx_formula))
            self.ErrorsPrinter.print_recursively(self.suspicious_counters, xlsx_formula)

    def find_unusual_counters(self, kpi_id, xlsx_formula):
        """
        Check for unusual counters, that is different than e.g. [M8011C239] form,
        idea is to find string without digits between brackets, check if first
        character of counter ID is 'M' and check for occurence of brackets '[', ']'

        :param kpi_id: analyzed kpi ID
        :param xlsx_formula: analyzed formula
        :return: None
        """
        try:
            self.suspicious_counters = []
            self.counters_from_formula = set()

            for i, char in enumerate(xlsx_formula):
                if char == '[':
                    end_of_numeric_fragment = xlsx_formula.find(']', i, len(xlsx_formula))

                    # Checking for unusual counters
                    if not (any(char.isdigit() for char in xlsx_formula[i + 1: end_of_numeric_fragment])) or \
                            xlsx_formula[i + 1] != "M" or ' ' in xlsx_formula[i + 1: end_of_numeric_fragment]:
                        self.suspicious_counters.append(xlsx_formula[i + 1: end_of_numeric_fragment])
                    self.counters_from_formula.add(xlsx_formula[i + 1: end_of_numeric_fragment])
        except Exception as other_errors:
            print(other_errors, "occured when trying to examine the", kpi_id, "formula in order to find unusual counters")
            self.logger.warning(other_errors, "occured when trying to examine the", kpi_id, "formula in order to find unusual counters")

    def handle_unintended_phrase_error(self, ar_range_beg, ar_range_end, nested, kpi_id):
        """
        Check for unusual and thus probably wrong phrases, idea is to find ranges witch
        arithmetic operators defined in self.__arithmetic_operators list as endpoints, without any
        digit characters in them .

        :param ar_range_beg: First index of arithmetic range, that is index of penultimate occurrence
        of arithmetic character in KPI's formula
        :param param ar_range_end: Last index of arithmetic range, that is index of penultimate occurrence
        of arithmetic character in KPI's formula
        :param nested: analyzed kpi's data
        :param kpi_id: analyzed kpi ID

        :return: None
        """
        try:
            if (not (any(char_in_arithmetic_range.isdigit() for char_in_arithmetic_range
                in nested["FORMULA"][ar_range_beg: ar_range_end]))) or ('[' not in nested["FORMULA"][ar_range_beg: ar_range_end]
                                                                        and ']' not in nested["FORMULA"][ar_range_beg: ar_range_end]
                                                                        and not nested["FORMULA"][ar_range_beg + 1:
                                                                                                  ar_range_end].replace(" ", "").isdigit()):
                if (len(nested["FORMULA"][ar_range_beg: ar_range_end].replace(" ", "")) > 2
                        and nested["FORMULA"][ar_range_beg if ar_range_beg == 0 and nested["FORMULA"][ar_range_beg] != "("
                    else ar_range_beg + 1: ar_range_end].replace(" ", "").lower()
                        not in self.formula_fragments_to_capitalize and nested["FORMULA"]
                        [ar_range_beg if ar_range_beg == 0 and nested["FORMULA"][ar_range_beg] != "(" else ar_range_beg + 1:
                    ar_range_end].replace(" ", "") not in
                        self.accurate_phrases_used_in_formulas):
                    self.potential_unintended_phrases.append(nested["FORMULA"][ar_range_beg if ar_range_beg == 0
                                                                               else ar_range_beg + 1: ar_range_end])
                    self.logger.warning("Formula may include an unintended "
                                        "phrase {} : {}".format(kpi_id, nested["FORMULA"]))
        except Exception as other_errors:
            print("{} occured when trying to examin the {} formula in order to find double asterisk error".format(
                other_errors,
                kpi_id
            ))
            self.logger.warning("{} occured when trying to examin the {} formula in order to find double asterisk error".format(
                other_errors,
                kpi_id
            ))

    def check_for_unintended_phrases(self, xlsx_formula, kpi_id):
        """
        Check if unintended phrases were found in __handle_unintended_phrase_error()
        if yes they are printed

        :param kpi_id: analyzed kpi ID
        :param xlsx_formula: analyzed formula

        :return: None
        """
        if self.potential_unintended_phrases:
            self.found_errors.append("Unusual phrases: {}    (This phrase may be not translated"
                                     " into a counter value or treated as EXCEL function, thus calculated"
                                     " formula may produce an 'NA' value)".
                                     format(" ".join(list(dict.fromkeys(self.potential_unintended_phrases)))))
            self.ErrorsPrinter.warn_print("May be an unintended phrase", "{} :".format(kpi_id), "")
            self.ErrorsPrinter.print_recursively(self.potential_unintended_phrases, xlsx_formula)
